example_request.javascript:
const response = await fetch("/v1/videos", {
  method: "POST",
  headers: { authorization: `Bearer ${process.env.AZIZAM_API_KEY}`, 'content-type': 'application/json' },
  body: JSON.stringify({
  "model": "video-ltx-2.5-i2v",
  "prompt": "A small teal fish mark on a clean white card.",
  "negative_prompt": "value",
  "seed": 0,
  "input_reference": "value",
  "image_strength": 0.7,
  "seconds": 1.0,
  "size": "1024x1024"
}),
});
if (!response.ok) throw new Error(await response.text());
console.log(await response.json());

